def adapt_contexts(docs):
    out = []
    for rank, doc in enumerate(docs, 1):
        meta = doc.get("metadata") or {}
        out.append(context(rank, doc.get("content"), legal_code(meta.get("doc_code")),
                           article_number(meta.get("article"))))
    return out
